files.expect-deadline.exp:
log_user 0
log_file -a -noappend "$env(HOME)/expect.raw"
set timeout 4
set f [open "$env(HOME)/metrics" w]
proc rec {k v} { global f; puts $f "$k=$v"; flush $f }
proc child_status {w} {
    if {[llength $w] != 4 || [lindex $w 2] != 0} { return abnormal }
    return [lindex $w 3]
}
spawn /usr/bin/python3 /opt/bashos-parity/harness/helpers/terminal-review-observer.py producer stream
expect -re {READY\r\n} { rec ready 0 } timeout { rec ready 1 } eof { rec ready 2 }
send "go\n"
set t0 [clock microseconds]
set r unset
expect -timeout 3 -re {NEVER_MATCH_THIS} { set r 0 } timeout { set r 1 } eof { set r 2 }
rec wait $r
rec elapsed_ms [expr {([clock microseconds] - $t0) / 1000.0}]
send "stop\n"
expect -timeout 3 eof {} timeout { rec drain timeout }
catch {close}
rec close [child_status [wait]]
close $f
log_file
exit 0

